"""Maintain full declarative contract adapters; no clauses supplied by the LLM."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / 'backend/app/templates'


def f(key, label, question, kind='text', optional=False, **extra):
    return dict(key=key, label=label, question=question, kind=kind, optional=optional, **extra)


def block(text, role='body', **extra): return dict(text=text, role=role, **extra)


def base(key, title, roles):
    left, right = roles
    genitive = {'Наймодатель':'Наймодателя','Наниматель':'Нанимателя','Заказчик':'Заказчика',
        'Исполнитель':'Исполнителя','Подрядчик':'Подрядчика','Займодавец':'Займодавца','Заёмщик':'Заёмщика'}
    fields = [f('sender', left, f'Укажите полное ФИО или наименование стороны «{left}».'),
        f('sender_address', 'Адрес ' + genitive[left], f'Какой полный адрес стороны «{left}» нужно указать?', 'address'),
        f('sender_details', 'Реквизиты ' + genitive[left], f'Какие паспортные данные или реквизиты организации стороны «{left}» известны? Неизвестные можно дополнить позже.'),
        f('recipient', right, f'Укажите полное ФИО или наименование стороны «{right}».'),
        f('recipient_address', 'Адрес ' + genitive[right], f'Какой полный адрес стороны «{right}» нужно указать?', 'address'),
        f('recipient_details', 'Реквизиты ' + genitive[right], f'Какие паспортные данные или реквизиты организации стороны «{right}» известны?')]
    blocks = [block(title, 'title'), block('{{place}}                                        {{date}}', 'place_date'),
        block(f'{left}: {{{{sender}}}}, адрес: {{{{sender_address}}}}. Реквизиты: {{{{sender_details}}}}.'),
        block(f'{right}: {{{{recipient}}}}, адрес: {{{{recipient_address}}}}. Реквизиты: {{{{recipient_details}}}}.'),
        block('Указанные лица, далее совместно именуемые «Стороны», заключили настоящий договор о нижеследующем.')]
    return fields, blocks


def finish(key, title, roles, fields, blocks, source_urls):
    maintained = ROOT / 'documents' / (key + '.json')
    if maintained.is_file() and json.loads(maintained.read_text(encoding='utf-8')).get('docx_asset'):
        print('Keeping maintained DOCX adapter:', key)
        return
    fields += [f('attachments', 'Приложения к договору', 'Какие приложения стороны включают в договор? Например, опись или техническое задание. Можно ответить «нет».'),
        f('place', 'Место заключения', 'В каком населённом пункте заключается договор?'),
        f('date', 'Дата договора', 'Какую дату заключения договора указываем?', 'date'),
        f('signature', 'Подписант первой стороны', f'Кто подпишет договор от стороны «{roles[0]}»?'),
        f('counterparty_signature', 'Подписант второй стороны', f'Кто подпишет договор от стороны «{roles[1]}»?')]
    blocks += [block('Приложения', 'heading'), block('{{attachments}}', 'attachments'),
        block('Подписи сторон', 'heading'), block(roles[0] + ': __________________ / {{signature}} /', 'signature'),
        block(roles[1] + ': __________________ / {{counterparty_signature}} /', 'signature')]
    package = dict(scenario=key, version=2, schema_version=2, coverage='structured',
        source='Самостоятельная полная форма с отдельными условиями сторон и проверяемыми нормативными ориентирами',
        usage_basis='Самостоятельная редакция; чужие коммерческие формы и их условия не копируются автоматически.',
        source_urls=source_urls, checked_at='2026-10-25', review_status='source_checked_draft', reviewed_by=None, reviewed_at=None,
        layout='contract', limitations=['Условия сторон не заменяют проверку императивных требований закона.',
            'Неподтверждённые условия, гарантии, штрафы и согласия не добавляются.',
            'Форма применяется только к указанному виду договора; специальные и неподдерживаемые договоры требуют отдельной формы.'], blocks=blocks)
    (ROOT / 'intake').mkdir(exist_ok=True)
    (ROOT / 'intake' / (key + '.json')).write_text(json.dumps(dict(scenario=key, version=2, fields=fields), ensure_ascii=False, indent=2), encoding='utf-8')
    (ROOT / 'documents' / (key + '.json')).write_text(json.dumps(package, ensure_ascii=False, indent=2), encoding='utf-8')


def housing():
    key = 'contract_housing'; title = 'Договор найма жилого помещения'; roles = ('Наймодатель', 'Наниматель')
    fields, blocks = base(key, title, roles)
    fields += [f('property', 'Адрес передаваемого жилья', 'Какой полный адрес квартиры или другого жилого помещения передаётся внаём?', 'address'),
        f('property_description', 'Характеристики жилья', 'Каковы вид помещения, площадь, число комнат и другие известные характеристики жилья?'),
        f('ownership', 'Полномочия наймодателя', 'На каком основании Наймодатель вправе передать жильё? Укажите известный документ о праве или полномочиях.'),
        f('residents', 'Проживающие с нанимателем', 'Кто будет постоянно проживать вместе с Нанимателем? Если никто, ответьте «нет».'),
        f('start_date', 'Начало найма', 'С какой даты начинается наём?', 'date'),
        f('term', 'Продолжительность найма', 'На какой срок стороны заключают договор? Например, 2 года или 11 месяцев.', 'duration'),
        f('amount', 'Ежемесячная плата', 'Какова согласованная месячная плата за жильё в рублях?', 'money'),
        f('payment', 'Порядок оплаты', 'До какого числа каждого месяца и каким способом вносится плата?'),
        f('utilities', 'Коммунальные и прочие платежи', 'Как стороны распределяют коммунальные платежи и другие расходы на содержание жилья?'),
        f('deposit', 'Наличие обеспечительного платежа', 'Предусмотрен обеспечительный платёж? Ответьте «да» или «нет».', 'choice', choices=['да', 'нет']),
        f('deposit_amount', 'Сумма обеспечительного платежа', 'Какова сумма обеспечительного платежа?', 'money', when_field='deposit', when_values=['да']),
        f('deposit_terms', 'Условия обеспечительного платежа', 'Когда вносится обеспечительный платёж и при каких согласованных условиях он возвращается или засчитывается?', when_field='deposit', when_values=['да']),
        f('handover', 'Передача жилья', 'Когда и в каком состоянии передаётся жильё? Как фиксируются имущество, ключи, счётчики и имеющиеся недостатки?'),
        f('repairs', 'Ремонт и обслуживание', 'Как стороны согласовали текущий ремонт, капитальный ремонт и устранение неисправностей? Если не согласовали, так и напишите.'),
        f('access', 'Доступ наймодателя', 'Как стороны согласовали доступ Наймодателя в жильё и предварительное уведомление Нанимателя?'),
        f('liability', 'Ответственность', 'Какие условия ответственности стороны согласовали? Штрафы без согласования не добавляются.'),
        f('termination', 'Изменение и прекращение', 'Как стороны согласовали изменение и прекращение договора и уведомления об этом?'),
        f('return_terms', 'Возврат жилья', 'В какой срок и в каком порядке жильё и имущество возвращаются Наймодателю?'),
        f('additional_terms', 'Дополнительные согласованные условия', 'Есть ли дополнительные согласованные условия — например, о животных или поднайме? Если нет, ответьте «нет».', optional=True)]
    blocks += [block('1. Предмет договора', 'heading'),
        block('Наймодатель предоставляет Нанимателю за плату во владение и пользование для проживания жилое помещение по адресу: {{property}}. Характеристики помещения: {{property_description}}.'),
        block('Основание права или полномочий Наймодателя: {{ownership}}.'),
        block('Постоянно проживающие совместно с Нанимателем лица: {{residents}}.'),
        block('2. Срок и передача помещения', 'heading'), block('Дата начала найма: {{start_date}}. Продолжительность найма: {{term}}.'), block('{{handover}}'),
        block('3. Плата и расчёты', 'heading'), block('Ежемесячная плата за наём составляет {{amount}}. Порядок внесения платы: {{payment}}.'), block('Распределение коммунальных и прочих платежей: {{utilities}}.'),
        block('Обеспечительный платёж не предусмотрен.', when_field='deposit', when_value='нет'),
        block('Обеспечительный платёж составляет {{deposit_amount}}. Условия внесения, зачёта и возврата: {{deposit_terms}}.', when_field='deposit', when_value='да'),
        block('4. Права и обязанности сторон', 'heading'), block('Помещение предоставляется для проживания. Наниматель обязан использовать его по назначению, обеспечивать сохранность и своевременно вносить согласованные платежи.'),
        block('Условия ремонта и обслуживания: {{repairs}}.'), block('Порядок доступа Наймодателя: {{access}}.'),
        block('5. Ответственность', 'heading'), block('{{liability}}'),
        block('6. Изменение, прекращение и возврат', 'heading'), block('{{termination}}'), block('{{return_terms}}'),
        block('7. Прочие условия', 'heading'), block('{{additional_terms}}', when_field='additional_terms', when_status='filled'),
        block('Вопросы, не урегулированные настоящим договором, разрешаются в соответствии с применимыми нормами законодательства Российской Федерации. Изменения и дополнения оформляются сторонами в письменной форме.')]
    finish(key, title, roles, fields, blocks, ['https://www.consultant.ru/document/cons_doc_LAW_9027/'])


def services_or_work(work=False):
    key = 'contract_work' if work else 'contract_services'
    title = 'Договор подряда' if work else 'Договор возмездного оказания услуг'
    roles = ('Заказчик', 'Подрядчик' if work else 'Исполнитель')
    fields, blocks = base(key, title, roles)
    fields += [f('subject', 'Предмет договора', 'Какие конкретные работы и результат заказывает Заказчик?' if work else 'Какие конкретные услуги заказывает Заказчик?'),
        f('scope', 'Объём и требования', 'Каковы объём, требования к качеству и согласованные ограничения задания?'),
        f('materials', 'Материалы и исходные данные', 'Кто предоставляет материалы, оборудование или исходные данные и на каких условиях?'),
        f('term', 'Сроки и этапы', 'Какие даты начала, завершения и промежуточные этапы согласованы?'),
        f('amount', 'Цена договора', 'Какова согласованная цена договора в рублях?', 'money'),
        f('payment', 'Порядок расчётов', 'Как согласованы аванс, остальные платежи, сроки оплаты и способ расчётов?'),
        f('acceptance', 'Приёмка', 'Как и в какой срок Заказчик принимает результат или подтверждает оказание услуг и сообщает о замечаниях?'),
        f('changes', 'Изменение задания и цены', 'Как согласовываются дополнительные работы или услуги, изменение цены и сроков?'),
        f('quality', 'Устранение недостатков', 'Как стороны согласовали устранение недостатков и гарантийные обязательства?'),
        f('liability', 'Ответственность', 'Какие условия ответственности согласованы? Несогласованные штрафы не добавляются.'),
        f('termination', 'Изменение и прекращение', 'Как согласованы изменение, отказ от исполнения или расторжение договора и расчёты при прекращении?'),
        f('additional_terms', 'Дополнительные условия', 'Какие дополнительные условия стороны согласовали? Можно ответить «нет».', optional=True)]
    performer = roles[1]
    blocks += [block('1. Предмет и объём', 'heading'), block(f'{performer} выполняет задание Заказчика: {{{{subject}}}}. Объём и требования: {{{{scope}}}}.'),
        block('Предоставление материалов, оборудования и исходных данных: {{materials}}.'), block('2. Сроки', 'heading'), block('{{term}}'),
        block('3. Цена и расчёты', 'heading'), block('Согласованная цена договора: {{amount}}. Порядок расчётов: {{payment}}.'),
        block('4. Исполнение и приёмка', 'heading'), block('{{acceptance}}'), block('Порядок изменения задания, цены и сроков: {{changes}}.'),
        block('5. Качество и недостатки', 'heading'), block('{{quality}}'), block('6. Ответственность', 'heading'), block('{{liability}}'),
        block('7. Изменение и прекращение', 'heading'), block('{{termination}}'), block('8. Прочие условия', 'heading'),
        block('{{additional_terms}}', when_field='additional_terms', when_status='filled'), block('Неурегулированные вопросы разрешаются по применимым нормам законодательства Российской Федерации. Условия, противоречащие императивным нормам, не приобретают силу вследствие включения в договор.')]
    finish(key, title, roles, fields, blocks, ['https://www.consultant.ru/document/cons_doc_LAW_9027/'])


def loan():
    key='contract_loan'; title='Договор займа'; roles=('Займодавец', 'Заёмщик'); fields,blocks=base(key,title,roles)
    fields += [f('amount', 'Сумма займа', 'Какова сумма займа в рублях?', 'money'),
        f('transfer', 'Передача займа', 'Когда и каким способом передаются деньги и чем подтверждается передача? Уточните, уже состоялась она или только планируется.'),
        f('interest_type', 'Условие о процентах', 'Стороны согласовали процентный или беспроцентный заём?', 'choice', choices=['процентный', 'беспроцентный']),
        f('interest', 'Размер и уплата процентов', 'Какая ставка, база расчёта и порядок уплаты процентов согласованы?', when_field='interest_type', when_values=['процентный']),
        f('term', 'Срок займа', 'Какой срок возврата займа согласован? Укажите известную дату либо согласованное правило определения срока.'),
        f('repayment', 'Возврат займа', 'Как возвращается сумма займа: целиком или по графику, каким способом и по каким реквизитам?'),
        f('early_repayment', 'Досрочный возврат', 'Как стороны согласовали досрочный возврат и уведомление об этом?'),
        f('liability', 'Ответственность', 'Какие условия ответственности за нарушение согласованы? Несогласованные неустойки не добавляются.'),
        f('termination', 'Изменение и прекращение', 'Как стороны согласовали изменение договора и расчёты при его прекращении?'),
        f('additional_terms', 'Дополнительные условия', 'Какие дополнительные условия согласованы? Если обеспечение оформляется отдельно, укажите это. Можно ответить «нет».', optional=True)]
    blocks += [block('1. Сумма и передача займа','heading'),block('Сумма займа составляет {{amount}}. Передача и её подтверждение: {{transfer}}.'),
        block('2. Проценты','heading'),block('Стороны согласовали беспроцентный заём.',when_field='interest_type',when_value='беспроцентный'),
        block('Стороны согласовали процентный заём. Размер и порядок уплаты процентов: {{interest}}.',when_field='interest_type',when_value='процентный'),
        block('3. Возврат займа','heading'),block('Срок возврата: {{term}}. Порядок возврата: {{repayment}}.'),block('Досрочный возврат: {{early_repayment}}.'),
        block('4. Ответственность','heading'),block('{{liability}}'),block('5. Изменение и прекращение','heading'),block('{{termination}}'),
        block('6. Прочие условия','heading'),block('{{additional_terms}}',when_field='additional_terms',when_status='filled'),
        block('Факт передачи займа подтверждается соответствующим документом о передаче денежных средств. Изменения и дополнения к договору оформляются сторонами в письменной форме.')]
    finish(key,title,roles,fields,blocks,['https://www.consultant.ru/document/cons_doc_LAW_9027/'])


if __name__ == '__main__':
    housing(); services_or_work(); services_or_work(True); loan()
    print('Updated four full contract forms and their declarative intakes')
